import React, { useState, useEffect } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import Navbar from './Navbar';
import { removeFromCart, updateQuantity } from '../actions/cartActions';
import '../Styles/Style.css';

const Cart = () => {
  const cartItems = useSelector((state) => state.cart.items);
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [clientData, setClientData] = useState({
    firstName: '',
    lastName: '',
    number: '',
    email: '',
    address: ''
  });

  useEffect(() => {
    const storedClientData = JSON.parse(localStorage.getItem('clientData'));
    if (storedClientData) {
      setClientData(storedClientData);
    }
  }, []);

  const handleRemoveFromCart = (id) => {
    dispatch(removeFromCart(id));
  };

  const handleQuantityChange = (id, quantity) => {
    if (quantity >= 1) {
      dispatch(updateQuantity(id, quantity));
    }
  };

  const handleContinuePurchase = () => {
    setIsModalOpen(true);
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setClientData({ ...clientData, [name]: value });
  };

  const handleConfirm = (e) => {
    e.preventDefault();
    localStorage.setItem('clientData', JSON.stringify(clientData));
    navigate('/purchase');
  };

  return (
    <>
      <Navbar />
      <div className="cart-container">
        <h2>Your Cart</h2>
        {cartItems.length === 0 ? (
          <p>Your cart is empty</p>
        ) : (
          cartItems.map((item) => (
            <div key={item.id} className="cart-item">
              <img src={item.images[0]} alt={item.name} />
              <div className="cart-item-details">
                <h3>{item.name}</h3>
                <p>{item.description}</p>
                <p>Price: ${item.price}</p>
              </div>
              <div className="cart-item-actions">
                <div className="quantity">
                  <label htmlFor={`quantity-${item.id}`}>Quantity:</label>
                  <button onClick={() => handleQuantityChange(item.id, item.quantity - 1)}>-</button>
                  <input
                    type="number"
                    id={`quantity-${item.id}`}
                    name="quantity"
                    value={item.quantity}
                    onChange={(e) => handleQuantityChange(item.id, Number(e.target.value))}
                    min="1"
                  />
                  <button onClick={() => handleQuantityChange(item.id, item.quantity + 1)}>+</button>
                </div>
                <button onClick={() => handleRemoveFromCart(item.id)}>Remove</button>
              </div>
            </div>
          ))
        )}
        {cartItems.length > 0 && (
          <div className="cart-actions">
            <button className="continue-purchase" onClick={handleContinuePurchase}>Continue Purchase</button>
          </div>
        )}
      </div>

      {isModalOpen && (
        <div className="modal">
          <div className="modal-content">
            <span className="close" onClick={handleCloseModal}><i className="bi bi-x-lg"></i></span>
            <h2>Enter Your Details</h2>
            <form onSubmit={handleConfirm}>
              <div className="form-group">
                <label htmlFor="firstName">First Name:</label>
                <input type="text" id="firstName" name="firstName" value={clientData.firstName} onChange={handleInputChange} required />
              </div>
              <div className="form-group">
                <label htmlFor="lastName">Last Name:</label>
                <input type="text" id="lastName" name="lastName" value={clientData.lastName} onChange={handleInputChange} required />
              </div>
              <div className="form-group">
                <label htmlFor="number">Number:</label>
                <input type="tel" id="number" name="number" value={clientData.number} onChange={handleInputChange} required />
              </div>
              <div className="form-group">
                <label htmlFor="email">Email:</label>
                <input type="email" id="email" name="email" value={clientData.email} onChange={handleInputChange} required />
              </div>
              <div className="form-group">
                <label htmlFor="address">Address:</label>
                <input type="text" id="address" name="address" value={clientData.address} onChange={handleInputChange} required />
              </div>
              <button type="submit" className="confirm-button">Confirm</button>
            </form>
          </div>
        </div>
      )}
    </>
  );
};

export default Cart;