import React, { useState } from 'react';
import { collection, getDocs, query, where } from 'firebase/firestore';
import { firestore } from '../firebase';
import '../Styles/Style.css';

const Admin = () => {
  const [orders, setOrders] = useState([]);
  const [isAdmin, setIsAdmin] = useState(false);
  const [email, setEmail] = useState('');
  const [passcode, setPasscode] = useState('');
  const [error, setError] = useState('');

  const handleLogin = async (e) => {
    e.preventDefault();
    try {
      const adminsCollection = collection(firestore, 'admins');
      const q = query(adminsCollection, where('email', '==', email), where('passcode', '==', passcode));
      const querySnapshot = await getDocs(q);
      if (!querySnapshot.empty) {
        setIsAdmin(true);
        fetchOrders();
      } else {
        setError('Invalid email or passcode');
      }
    } catch (error) {
      console.error('Error logging in: ', error);
      setError('Error logging in');
    }
  };

  const fetchOrders = async () => {
    const ordersCollection = collection(firestore, 'orders');
    const ordersSnapshot = await getDocs(ordersCollection);
    const ordersList = ordersSnapshot.docs.map(doc => doc.data());
    setOrders(ordersList);
  };

  if (!isAdmin) {
    return (
      <>
        <div className="login-container">
          <h2>Admin Login</h2>
          <form onSubmit={handleLogin}>
            <div className="form-group">
              <label htmlFor="email">Email:</label>
              <input
                type="email"
                id="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
              />
            </div>
            <div className="form-group">
              <label htmlFor="passcode">Passcode:</label>
              <input
                type="password"
                id="passcode"
                value={passcode}
                onChange={(e) => setPasscode(e.target.value)}
                required
              />
            </div>
            {error && <p className="error">{error}</p>}
            <button type="submit" className="login-button">Login</button>
          </form>
        </div>
      </>
    );
  }

  return (
    <>
      <div className="admin-container">
        <h2>Admin Dashboard</h2>
        <table className="orders-table">
          <thead>
            <tr>
              <th>Client Name</th>
              <th>Email</th>
              <th>Order Details</th>
              <th>Total Price</th>
              <th>Timestamp</th>
            </tr>
          </thead>
          <tbody>
            {orders.map((order, index) => (
              <tr key={index}>
                <td>{order.clientData.firstName} {order.clientData.lastName}</td>
                <td>{order.clientData.email}</td>
                <td>
                  <ul>
                    {order.cartItems.map((item, idx) => (
                      <li key={idx}>{item.name} - {item.quantity} x ${item.price}</li>
                    ))}
                  </ul>
                </td>
                <td>${order.totalPrice}</td>
                <td>{new Date(order.timestamp.seconds * 1000).toLocaleString()}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </>
  );
};

export default Admin;