import React, { useState } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { collection, addDoc } from 'firebase/firestore';
import { jsPDF } from 'jspdf';
import autoTable from 'jspdf-autotable';
import { firestore } from '../firebase';
import Navbar from './Navbar';
import { clearCart } from '../actions/cartActions';
import '../Styles/Style.css';

const Purchase = () => {
  const cartItems = useSelector((state) => state.cart.items);
  const clientData = JSON.parse(localStorage.getItem('clientData'));
  const [isSuccessModalOpen, setIsSuccessModalOpen] = useState(false);
  const navigate = useNavigate();
  const dispatch = useDispatch();

  const totalPrice = cartItems.reduce((total, item) => total + item.price * item.quantity, 0);

  const generatePDF = () => {
    const doc = new jsPDF();
    doc.text(`Dear ${clientData.firstName},`, 10, 10);
    doc.text('Here are the details of your purchase:', 10, 20);
    autoTable(doc, {
      head: [['Product', 'Quantity', 'Price', 'Total']],
      body: cartItems.map(item => [item.name, item.quantity, `$${item.price}`, `$${item.price * item.quantity}`]),
    });
    doc.text(`Total Price: $${totalPrice}`, 10, doc.autoTable.previous.finalY + 10);
    return doc.output('datauristring');
  };

  const handleConfirmPurchase = async () => {
    try {
      const pdfDataUri = generatePDF();

      // Save client data and command to Firestore
      await addDoc(collection(firestore, 'orders'), {
        clientData,
        cartItems,
        totalPrice,
        pdfDataUri,
        timestamp: new Date()
      });
      setIsSuccessModalOpen(true);
    } catch (error) {
      console.error('Error adding document: ', error);
    }
  };

  const handleCloseSuccessModal = () => {
    setIsSuccessModalOpen(false);
    dispatch(clearCart());
    navigate('/arch');
  };

  return (
    <>
      <Navbar />
      <div className="purchase-container">
        <h2>Dear {clientData.firstName},</h2>
        <p>Here are the details of your purchase:</p>
        <table>
          <thead>
            <tr>
              <th>Product</th>
              <th>Quantity</th>
              <th>Price</th>
              <th>Total</th>
            </tr>
          </thead>
          <tbody>
            {cartItems.map((item) => (
              <tr key={item.id}>
                <td>{item.name}</td>
                <td>{item.quantity}</td>
                <td>${item.price}</td>
                <td>${item.price * item.quantity}</td>
              </tr>
            ))}
          </tbody>
        </table>
        <h3>Total Price: ${totalPrice}</h3>
        <button className="confirm-purchase" onClick={handleConfirmPurchase}>Confirm Purchase</button>
      </div>

      {isSuccessModalOpen && (
        <div className="modal">
          <div className="modal-content">
            <span className="close" onClick={handleCloseSuccessModal}><i className="bi bi-x-lg"></i></span>
            <div className="success-message">
              <i className="bi bi-check-circle-fill"></i>
              <h2>Success!</h2>
              <p>Your order has been confirmed. Please check your WhatsApp or email for more information.</p>
              <button onClick={handleCloseSuccessModal} className="confirm-button">OK</button>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default Purchase;