import React, { useState, useEffect } from 'react';
import 'animate.css';
import '../Styles/Style.css';

const products = [
  {
    id: 1,
    image: `${process.env.PUBLIC_URL}/images/img-1.jpg`,
    price: '$10.00'
  },
  {
    id: 2,
    image: `${process.env.PUBLIC_URL}/images/img-2.jpg`,
    price: '$20.00'
  },
  {
    id: 3,
    image: `${process.env.PUBLIC_URL}/images/img-3.jpg`,
    price: '$30.00'
  }
];

const Slideshow = () => {
  const [currentSlide, setCurrentSlide] = useState(0);
  const [animation, setAnimation] = useState('animate__fadeIn');

  const nextSlide = () => {
    setAnimation('animate__fadeOutLeft');
    setTimeout(() => {
      setCurrentSlide((prevSlide) => (prevSlide + 1) % products.length);
      setAnimation('animate__fadeInRight');
    }, 500);
  };

  const prevSlide = () => {
    setAnimation('animate__fadeOutRight');
    setTimeout(() => {
      setCurrentSlide((prevSlide) => (prevSlide - 1 + products.length) % products.length);
      setAnimation('animate__fadeInLeft');
    }, 500);
  };

  useEffect(() => {
    const interval = setInterval(nextSlide, 8000); // Change slide every 8 seconds
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="slideshow-container">
      {products.map((product, index) => (
        <div key={product.id} className={`slide ${index === currentSlide ? 'active' : ''} animate__animated ${animation}`}>
          <img src={product.image} alt={`Product ${product.id}`} />
          <div className="slide-content">
            <p>{product.price}</p>
            <button>More Details <i className="bi bi-info-circle-fill m-1 p-1"></i></button>
          </div>
        </div>
      ))}
      <button className="prev" onClick={prevSlide}>&#10094;</button>
      <button className="next" onClick={nextSlide}>&#10095;</button>
    </div>
  );
};

export default Slideshow;